function validate([s, queries]) {
  if (typeof s !== 'string' || !/^[a-z]+$/.test(s)) return 's must be a non-empty string of lowercase letters.';
  if (s.length < 2 || s.length > 100000 || s.length % 2 !== 0) return 's must have an even length from 2 to 10^5.';
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 100000) return 'queries needs 1 to 10^5 entries.';
  const n = s.length, half = n / 2;
  for (const q of queries) {
    if (!Array.isArray(q) || q.length !== 4 || q.some(v => !Number.isInteger(v))) return 'Each query is four whole numbers [a, b, c, d].';
    const [a, b, c, d] = q;
    if (!(0 <= a && a <= b && b < half)) return 'Each query needs 0 <= a <= b < n / 2.';
    if (!(half <= c && c <= d && d < n)) return 'Each query needs n / 2 <= c <= d < n.';
  }
  return null;
}

