function canMakePalindromeQueries(s, queries) {
  const n = s.length;
  const half = n / 2;
  // Pair i joins s[i] (left side) with s[n - 1 - i] (right side, read backwards).
  const countL = [new Array(26).fill(0)];
  const countR = [new Array(26).fill(0)];
  const mismatch = [0];
  for (let i = 0; i < half; i++) {
    const x = s.charCodeAt(i) - 97;
    const y = s.charCodeAt(n - 1 - i) - 97;
    countL.push(countL[i].slice());
    countR.push(countR[i].slice());
    countL[i + 1][x]++;
    countR[i + 1][y]++;
    mismatch.push(mismatch[i] + (x === y ? 0 : 1));
  }
  const amount = (count, from, to, letter) => count[to + 1][letter] - count[from][letter];
  const clean = (from, to) => mismatch[to + 1] === mismatch[from];
  const sameLetters = (first, second, from, to) => {
    for (let letter = 0; letter < 26; letter++) {
      if (amount(first, from, to, letter) !== amount(second, from, to, letter)) return false;
    }
    return true;
  };
  // [l1, r1] is the free range that starts first (counts in first), [l2, r2] the other one.
  const possible = (l1, r1, first, l2, r2, second) => {
    if (!clean(0, l1 - 1) || !clean(Math.max(r1, r2) + 1, half - 1)) {
      return false;
    }
    if (r2 <= r1) {
      return sameLetters(first, second, l1, r1);
    }
    if (r1 < l2) {
      return clean(r1 + 1, l2 - 1) && sameLetters(first, second, l1, r1) && sameLetters(first, second, l2, r2);
    }
    for (let letter = 0; letter < 26; letter++) {
      const spareFirst = amount(first, l1, r1, letter) - amount(second, l1, l2 - 1, letter);
      const spareSecond = amount(second, l2, r2, letter) - amount(first, r1 + 1, r2, letter);
      if (spareFirst < 0 || spareFirst !== spareSecond) {
        return false;
      }
    }
    return true;
  };
  return queries.map(([a, b, c, d]) => {
    const low = n - 1 - d;
    const high = n - 1 - c;
    return a <= low ? possible(a, b, countL, low, high, countR) : possible(low, high, countR, a, b, countL);
  });
}

