function canMakePalindromeQueries(s, queries) {
  // Try every arrangement of both ranges and test the whole string.
  const perms = arr => arr.length <= 1 ? [arr] : arr.flatMap((v, i) => perms([...arr.slice(0, i), ...arr.slice(i + 1)]).map(p => [v, ...p]));
  return queries.map(([a, b, c, d]) => {
    const chars = s.split('');
    for (const first of perms(chars.slice(a, b + 1))) {
      for (const second of perms(chars.slice(c, d + 1))) {
        const t = [...chars.slice(0, a), ...first, ...chars.slice(b + 1, c), ...second, ...chars.slice(d + 1)].join('');
        if (t === t.split('').reverse().join('')) return true;
      }
    }
    return false;
  });
}

