function generate(rand, size) {
  const large = size === 'large';
  const half = large ? 5000 : 1 + Math.floor(rand() * 4);
  const n = 2 * half;
  const letters = 1 + Math.floor(rand() * (large ? 4 : 3));
  const pick = () => String.fromCharCode(97 + Math.floor(rand() * letters));
  // Start from a palindrome (small inputs sometimes break a pair), then shuffle one block on each side.
  const chars = [];
  for (let i = 0; i < half; i++) chars.push(pick());
  for (let i = half - 1; i >= 0; i--) chars.push(!large && rand() < 0.15 ? pick() : chars[i]);
  const width = large ? 300 : half;
  const span = base => { const from = Math.floor(rand() * half); return [base + from, base + Math.min(half - 1, from + Math.floor(rand() * width))]; };
  const scramble = ([from, to]) => { for (let i = to; i > from; i--) { const j = from + Math.floor(rand() * (i - from + 1)); [chars[i], chars[j]] = [chars[j], chars[i]]; } };
  const leftMess = span(0), rightMess = span(half);
  scramble(leftMess);
  scramble(rightMess);
  const between = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const order = (x, y, lo, hi) => { x = Math.min(hi, Math.max(lo, x)); y = Math.min(hi, Math.max(lo, y)); return x <= y ? [x, y] : [y, x]; };
  const queries = [];
  const count = large ? 2000 : 1 + Math.floor(rand() * 5);
  for (let k = 0; k < count; k++) {
    const kind = rand();
    let a, b, c, d;
    if (kind < 0.6) {
      // Ranges that cover both shuffled blocks; some get one end nudged.
      a = between(0, leftMess[0]); b = between(leftMess[1], half - 1);
      c = between(half, rightMess[0]); d = between(rightMess[1], n - 1);
      if (kind < 0.3) {
        const shift = between(-3, 3), which = Math.floor(rand() * 4);
        if (which === 0) a += shift; else if (which === 1) b += shift; else if (which === 2) c += shift; else d += shift;
      }
    } else {
      [a, b] = span(0);
      [c, d] = span(half);
    }
    [a, b] = order(a, b, 0, half - 1);
    [c, d] = order(c, d, half, n - 1);
    queries.push([a, b, c, d]);
  }
  return [chars.join(''), queries];
}
